19	/// Build a logits arena from per-row logits (row `i` is token `i`'s logits).
20	fn make_arena(ctx: &DeviceContext, rows: &[Vec<f32>]) -> HiddenStates {
21	    let vocab = rows[0].len();
22	    assert!(rows.iter().all(|r| r.len() == vocab), "ragged rows");
23	    let mut hs = HiddenStates::zeros(ctx, vocab, rows.len()).unwrap();
24	    let flat: Vec<bf16> = rows
25	        .iter()
26	        .flat_map(|r| r.iter().map(|&x| bf16::from_f32(x)))
27	        .collect();
28	    ctx.stream.memcpy_htod(&flat, &mut hs.data).unwrap();
29	    ctx.sync().unwrap();
30	    hs
31	}
