57	#[test]
58	fn greedy_batch_picks_each_rows_argmax() {
59	    let ctx = DeviceContext::new().unwrap();
60	    let vocab = 16;
61	    let peaks = [3usize, 7, 0, 15];
62	    let rows: Vec<Vec<f32>> = peaks.iter().map(|&p| peak_row(vocab, p, 10.0)).collect();
63	    let arena = make_arena(&ctx, &rows);
64	    let params = vec![greedy(); peaks.len()];
65	    let mut scratch = SampleScratch::new(&ctx, vocab, peaks.len()).unwrap();
66	
67	    let tokens = select_batch(
68	        &ctx,
69	        &arena,
70	        &refs(&params),
71	        &vec![0; params.len()],
72	        0,
73	        &mut scratch,
74	    )
75	    .unwrap();
