80	#[test]
81	fn top_k_one_routes_through_greedy_path() {
82	    // High temperature but top_k == 1 => is_greedy() => argmax, not sampling.
83	    let ctx = DeviceContext::new().unwrap();
84	    let vocab = 16;
85	    let arena = make_arena(&ctx, &[peak_row(vocab, 5, 10.0)]);
86	    let params = vec![sampling(1.0, 1, 1.0)];
87	    let mut scratch = SampleScratch::new(&ctx, vocab, 1).unwrap();
