94	#[test]
95	fn mixed_batch_routes_and_places_each_row() {
96	    // Row 0 greedy, row 1 sampled, row 2 greedy. Row 1's top_p (0.5) sits above
97	    // the 1/vocab argmax floor so it genuinely takes the sampler path; its dist
98	    // is near one-hot (peak prob ~1) so the nucleus is the peak and the sample
99	    // collapses there. Verifies both paths run in one call and each token lands
100	    // at its own row index.
101	    let ctx = DeviceContext::new().unwrap();
102	    let vocab = 16;
103	    let rows = vec![
104	        peak_row(vocab, 2, 12.0),
105	        peak_row(vocab, 9, 12.0),
106	        peak_row(vocab, 4, 12.0),
107	    ];
108	    let arena = make_arena(&ctx, &rows);
109	    let params = vec![greedy(), sampling(1.0, -1, 0.5), greedy()];
110	    let mut scratch = SampleScratch::new(&ctx, vocab, 3).unwrap();
111	
112	    let tokens = select_batch(&ctx, &arena, &refs(&params), &[0, 0, 0], 7, &mut scratch).unwrap();
113	
114	    assert_eq!(tokens, vec![2, 9, 4]);
115	}
