117	#[test]
118	fn sampling_is_seed_deterministic_and_actually_samples() {
119	    // Uniform logits: argmax would always pick index 0, so seeing >1 token over
120	    // many seeds proves the non-greedy path samples; equal seeds proves it is
121	    // reproducible. Also exercises scratch reuse across many calls.
122	    let ctx = DeviceContext::new().unwrap();
123	    let vocab = 8;
124	    let arena = make_arena(&ctx, &[vec![0.0; vocab]]);
125	    let params = vec![sampling(1.0, -1, 1.0)];
126	    let mut scratch = SampleScratch::new(&ctx, vocab, 1).unwrap();
127	
128	    let a = select_batch(&ctx, &arena, &refs(&params), &[0], 42, &mut scratch).unwrap();
129	    let b = select_batch(&ctx, &arena, &refs(&params), &[0], 42, &mut scratch).unwrap();
130	    assert_eq!(a, b, "same seed must be deterministic");
131	
132	    let mut seen = HashSet::new();
133	    for s in 0..64u64 {
134	        seen.insert(select_batch(&ctx, &arena, &refs(&params), &[0], s, &mut scratch).unwrap()[0]);
135	    }
136	    assert!(
137	        seen.len() > 1,
138	        "uniform sampling should explore multiple tokens, saw {seen:?}"
139	    );
140	}
