180	#[test]
181	fn padded_arena_width_does_not_suppress_the_argmax_routing() {
182	    // qwen35 tile-aligns its logits width past the decodable vocab (#1046). A
183	    // top_p at exactly 1/decodable collapses to the argmax on the unpadded
184	    // arena, so it must still do so at twice the arena width.
185	    let ctx = DeviceContext::new().unwrap();
186	    let decodable = 256usize;
187	    let vocab = 2 * decodable;
188	    let lo = 128usize;
189	    let hi = 200usize;
190	    let mut row = vec![-1.0f32; vocab];
191	    row[lo] = 8.0; // bf16-exact, identical to `hi` -> a true top tie
192	    row[hi] = 8.0;
193	    let arena = make_arena(&ctx, &[row]);
194	
195	    let tiny = sampling(1.0, -1, 1.0 / decodable as f32);
196	
197	    // Control: at the arena width 1/256 is no longer a single-token nucleus,
198	    // and the sampler may return the tied peer.
199	    let mut wide = SampleScratch::new(&ctx, vocab, 1).unwrap();
200	    let mut sampled_the_peer = false;
201	    for s in 0..64u64 {
202	        let picked = select_batch(&ctx, &arena, &[&tiny], &[0], s, &mut wide).unwrap()[0];
203	        assert!(picked == lo as u32 || picked == hi as u32);
204	        sampled_the_peer |= picked == hi as u32;
205	    }
206	    assert!(
207	        sampled_the_peer,
208	        "control: an arena-width routing decision puts this row on the sampler"
209	    );
210	
211	    let mut bounded = SampleScratch::with_selection_width(&ctx, vocab, decodable, 1).unwrap();
212	    for s in 0..64u64 {
213	        assert_eq!(
214	            select_batch(&ctx, &arena, &[&tiny], &[0], s, &mut bounded).unwrap(),
215	            vec![lo as u32],
216	            "seed {s}: the decodable vocab must keep this row on the argmax path"
217	        );
218	    }
219	}
